import java.util.*;

class Solution {
  public int countCompleteSubstrings(String word, int k) {
    int n = word.length(), answer = 0;
    for (int left = 0; left < n; ) {
      int right = left + 1;
      while (right < n && Math.abs(word.charAt(right) - word.charAt(right - 1)) <= 2) right++;
      for (int distinct = 1; distinct <= 26; distinct++) {
        int len = distinct * k;
        if (len > right - left) break;
        int[] count = new int[26];
        int complete = 0;
        for (int i = left; i < right; i++) {
          int c = word.charAt(i) - 'a';
          if (count[c]++ == k) complete--;
          if (count[c] == k) complete++;
          if (i >= left + len) {
            int old = word.charAt(i - len) - 'a';
            if (count[old]-- == k) complete--;
            if (count[old] == k) complete++;
          }
          if (i >= left + len - 1 && complete == distinct) answer++;
        }
      }
      left = right;
    }
    return answer;
  }
}
